package com.darshan.airesumeanalyzer.dto.ai;

import java.io.Serializable;
import java.util.ArrayList;
import java.util.List;

/**
 * Top-level DTO representing personalized AI insights generated by Gemini.
 * Included in AnalysisResult and stored in the user's HTTP session.
 */
public class GeminiResumeAnalysis implements Serializable {

    private static final long serialVersionUID = 1L;

    public static final String DEFAULT_DISCLAIMER =
            "AI-generated insights are automated suggestions based on text extraction and may contain inaccuracies. Always review and verify before submitting your resume.";

    private boolean available;
    private String statusMessage;

    private String summary;
    private List<ResumeStrength> keyStrengths = new ArrayList<>();
    private List<ResumeSkillGap> skillGaps = new ArrayList<>();
    private List<ResumeImprovement> improvementSuggestions = new ArrayList<>();
    private List<ResumeBulletSuggestion> bulletPointImprovements = new ArrayList<>();
    private List<String> projectExperienceRecommendations = new ArrayList<>();
    private List<ResumeActionItem> actionPlan = new ArrayList<>();
    private String disclaimer = DEFAULT_DISCLAIMER;

    public GeminiResumeAnalysis() {
        this.available = false;
    }

    public static GeminiResumeAnalysis unavailable(String message) {
        GeminiResumeAnalysis analysis = new GeminiResumeAnalysis();
        analysis.setAvailable(false);
        analysis.setStatusMessage(message);
        return analysis;
    }

    // --- Getters and Setters ---

    public boolean isAvailable() {
        return available;
    }

    public void setAvailable(boolean available) {
        this.available = available;
    }

    public String getStatusMessage() {
        return statusMessage;
    }

    public void setStatusMessage(String statusMessage) {
        this.statusMessage = statusMessage;
    }

    public String getSummary() {
        return summary;
    }

    public void setSummary(String summary) {
        this.summary = summary;
    }

    public List<ResumeStrength> getKeyStrengths() {
        return keyStrengths;
    }

    public void setKeyStrengths(List<ResumeStrength> keyStrengths) {
        this.keyStrengths = keyStrengths != null ? keyStrengths : new ArrayList<>();
    }

    public List<ResumeSkillGap> getSkillGaps() {
        return skillGaps;
    }

    public void setSkillGaps(List<ResumeSkillGap> skillGaps) {
        this.skillGaps = skillGaps != null ? skillGaps : new ArrayList<>();
    }

    public List<ResumeImprovement> getImprovementSuggestions() {
        return improvementSuggestions;
    }

    public void setImprovementSuggestions(List<ResumeImprovement> improvementSuggestions) {
        this.improvementSuggestions = improvementSuggestions != null ? improvementSuggestions : new ArrayList<>();
    }

    public List<ResumeBulletSuggestion> getBulletPointImprovements() {
        return bulletPointImprovements;
    }

    public void setBulletPointImprovements(List<ResumeBulletSuggestion> bulletPointImprovements) {
        this.bulletPointImprovements = bulletPointImprovements != null ? bulletPointImprovements : new ArrayList<>();
    }

    public List<String> getProjectExperienceRecommendations() {
        return projectExperienceRecommendations;
    }

    public void setProjectExperienceRecommendations(List<String> projectExperienceRecommendations) {
        this.projectExperienceRecommendations = projectExperienceRecommendations != null ? projectExperienceRecommendations : new ArrayList<>();
    }

    public List<ResumeActionItem> getActionPlan() {
        return actionPlan;
    }

    public void setActionPlan(List<ResumeActionItem> actionPlan) {
        this.actionPlan = actionPlan != null ? actionPlan : new ArrayList<>();
    }

    public String getDisclaimer() {
        return disclaimer;
    }

    public void setDisclaimer(String disclaimer) {
        this.disclaimer = disclaimer;
    }
}
